import numpy as np
import pandas as pd
from pandas.core import nanops


def run_case(values, mask, name_prefix):
    # Try each nanarg... function and record its returned value.
    for func_name in ["nanargmax", "nanargmin", "nanmax", "nanmin"]:
        func = getattr(nanops, func_name)
        rec_name = (
            "values = np.array([2**63 + 1, 2**63 + 2, 2**63 + 3, 0], dtype=np.uint64); "
            "mask = np.zeros(4, dtype=bool); mask[na_pos] = True for na_pos in {0, 3}; "
            "valid = np.flatnonzero(~mask); nanops.nanargmax/nanargmin/nanmax/nanmin(values, mask=mask)"
        )
        try:
            probe(rec_name, func(values, mask=mask))
        except Exception as e:
            probe_exception(rec_name, e)
            return


# --- Scenario 1 ---
values = np.array([2**63 + 1, 2**63 + 2, 2**63 + 3, 0], dtype=np.uint64)
mask = np.zeros(4, dtype=bool)
for na_pos in {0, 3}:
    mask = np.zeros(4, dtype=bool)
    mask[na_pos] = True
    valid = np.flatnonzero(~mask)
    try:
        probe(
            "values = np.array([2**63 + 1, 2**63 + 2, 2**63 + 3, 0], dtype=np.uint64); mask = np.zeros(4, dtype=bool); mask[na_pos] = True for na_pos in {0, 3}; valid = np.flatnonzero(~mask); nanops.nanargmax/nanargmin/nanmax/nanmin(values, mask=mask)",
            {
                "nanargmax": nanops.nanargmax(values, mask=mask),
                "nanargmin": nanops.nanargmin(values, mask=mask),
                "nanmax": nanops.nanmax(values, mask=mask),
                "nanmin": nanops.nanmin(values, mask=mask),
            },
        )
    except Exception as e:
        probe_exception(
            "values = np.array([2**63 + 1, 2**63 + 2, 2**63 + 3, 0], dtype=np.uint64); mask = np.zeros(4, dtype=bool); mask[na_pos] = True for na_pos in {0, 3}; valid = np.flatnonzero(~mask); nanops.nanargmax/nanargmin/nanmax/nanmin(values, mask=mask)",
            e,
        )


# --- Scenario 2 ---
# For nanargmax: values = min int64
mask = np.array([True, False, False])
values = np.full(3, np.iinfo(np.int64).min, dtype=np.int64)
