    probe(
        "mask = np.array([True, False, False]); values = np.full(3, np.iinfo(np.int64).min, dtype=np.int64) for nanargmax; values = np.full(3, np.iinfo(np.int64).max, dtype=np.int64) for nanargmin",
        nanops.nanargmax(values, mask=mask),
